        location_observed TEXT,
        source_url TEXT,
        local_image_path TEXT,
        image_validation_status TEXT
    );
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_001','2025-04-06','FIDESZ-TÁBOR','STATE','Állami hirdetés (VOKS 2025)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„VOKS 2025 – Ne hagyjuk, hogy a fejünk felett döntsenek!”','Utcai hengeres hirdetőoszlopra (Litfaß-oszlopra) ragasztási folyamat közben fotózott plakát: elöl szigorúan néző Volodimir Zelenszkij, mögötte mosolygó Ursula von der Leyen és nevető Manfred Weber fekete-fehér portréja piros-fehér nyílgrafika előtt, alul VOKS [X] 2025 logó.','Hengeres hirdetőoszlop & Óriásplakát / Eurobillboard (12 m²)','NEGATIVE','Elrettentő / Szuverenitásvédelmi','Volodimir Zelenszkij, Ursula von der Leyen, Manfred Weber','Vertikális fenyegetés-hierarchia (felülről letekintő brüsszeli vezetők), fekete-fehér deheroizáló portrék, piros vészjelző ék.','Ukrajna EU-csatlakozását közvetlen biztonsági és gazdasági fenyegetésként keretező kormányzati kampány, amely a véleménynyilvánító szavazással (VOKS 2025) tematizálta a tavaszi politikai napirendet.','444.hu','444.hu','Budapest / Országos','https://444.hu/2025/04/06/itt-az-uj-plakatkampany-zelenszkij-szigoruan-nez-von-der-leyen-onelegulten-mosolyog-weber-pedig-ordogien-nevet','vagott_kepek/HUN_PLAKAT_2025_001.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_002','2025-07-01','FIDESZ-TÁBOR','STATE','Állami hirdetés (VOKS 2025 utókampány)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„Megmutattuk, hogy van véleményünk! 2 millió nem Ukrajna EU-tagságára!”','Hengeres utcai hirdetőoszlopon látható sötét tónusú plakát, középen magyar zászlókat lengető tömegfotóból megformált óriási X-szimbólummal és nagy fehér nagybetűs felirattal.','Hengeres hirdetőoszlop & Óriásplakát / Eurobillboard (12 m²)','MOBILIZING','Többséget demonstráló / Megerősítő','Brüsszel, Ukrajna EU-csatlakozása','Az X-szimbólum (szavazólap és stoptábla egyszerre) kitöltése nemzeti zászlós tömeggel: a kormányzati álláspontot népi konszenzusként jeleníti meg.','A véleménynyilvánító szavazás eredményét hirdető állami utókampány, amely a 2 milliós nem szavazat felmutatásával demokratikus többséget demonstrált a kormány vétópolitikája mögött.','HVG','Cabrera Martin / HVG','Budapest','https://hvg.hu/itthon/20250701_Uj-ukranellenes-plakatokkal-jelentkezett-a-kormany','vagott_kepek/HUN_PLAKAT_2025_002.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_003','2025-07-02','FIDESZ-TÁBOR','PROXY','Harmadik feles negatív kampány (NEM)','Nemzeti Ellenállás Mozgalom (Ellenállás Mozgalom Non-Profit Kft. – Apáti Bence)','„MINT KÉT TOJÁS – Zelenszkij / A magyar Zelenszkij”','Villamos-/buszmegálló citylight vitrinjében elhelyezett plakát: két törött tojáshéjban ülő, öltönyös, ukrán zászlót lengető Volodimir Zelenszkij és Magyar Péter karikatúra-montázsa kék háttér előtt.','Citylight vitrin (118,5 x 175 cm) & Óriásplakát (12 m²)','NEGATIVE','Szatirikus karaktertámadás / Összemosás','Magyar Péter, Volodimir Zelenszkij','Infantilizáló karikatúra (tojáshéjból kikelt ikrek), az ellenfél vizuális megfosztása a nemzeti szuverenitástól (ukrán zászló Magyar Péter kezében).','Az Apáti Bence-féle Nemzeti Ellenállás Mozgalom plakátja vizuálisan mosta össze Magyar Pétert Zelenszkijjel; a kampány diplomáciai vihart kavart, Kijev bekérette a magyar nagykövetet.','444.hu','Mészáros Juli / 444.hu','Budapest','https://444.hu/2025/07/02/dedokampanyban-mossa-ossze-az-apati-fele-mozgalom-zelenszkijt-es-magyar-petert','vagott_kepek/HUN_PLAKAT_2025_003.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_004','2025-07-12','FIDESZ-TÁBOR','PROXY','Mobil teherautós ellenkampány','Kormánypárti kampányfelület','„Volt egy zápor 😎”','A Tisza Párt nagykanizsai kongresszusának parkolójában leállított fehér kisteherautóra szerelt óriásplakát: viharos, villámló tengeren úszó rózsaszín fürdőkádban ülő, napszemüveges, kezében kézitükröt tartó öltönyös Magyar Péter.','Mobil óriásplakát teherautón (504 x 238 cm)','NEGATIVE','Helyszíni gerilla-trollkampány / Ironikus','Magyar Péter','Nárcizmus-szimbólumok (rózsaszín kád, arany kézitükör, napszemüveg emoji) szembeállítva a pusztító viharral: az empátiahiány és elitizmus vizuális vádja.','Célzott helyszíni trollkampány a Tisza Párt nagykanizsai kongresszusán, amely Magyar Péter nyári viharral kapcsolatos nyilatkozatát igyekezett komolytalanná tenni.','Telex','Telex','Nagykanizsa','https://telex.hu/belfold/2025/12/magyar-petert-gunyolo-plakat-varja-a-tiszasokat-a-kongresszus-helyszinen','vagott_kepek/HUN_PLAKAT_2025_004.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_005','2025-10-04','FIDESZ-TÁBOR','STATE','Állami hirdetés (Nemzeti Konzultáció 2025 ősz)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„Brüsszel bábjai adót akarnak emelni! – Tiltakozzunk az adóemelés ellen!”','Épület homlokzatára rögzített óriásplakát: sárga blézerben mosolygó Ursula von der Leyen mindkét kezével fajáték marionett-kereszteket és zsinórokat mozgat, jobb oldalon piros körben fehér felirat.','Óriásplakát / Eurobillboard (504 x 238 cm, 12 m²)','NEGATIVE','Szuverenitásvédelmi / Gazdasági elrettentő','Ursula von der Leyen, Brüsszel, hazai ellenzék','Klasszikus összeesküvés- és befolyás-szemiotika: a fizikai marionett-kereszt láthatóvá teszi a „háttérhatalmi irányítást”.','Az őszi Nemzeti Konzultációt népszerűsítő állami hirdetés, amely az ellenzéknek tulajdonított adóemelési terveket közvetlen brüsszeli megrendelésként keretezte.','HVG','Túry Gergely / HVG','Budapest','https://hvg.hu/itthon/20251004_Ursula-Von-der-Leyen-babozas-nemzeti-konzultacio-plakat-ebx','vagott_kepek/HUN_PLAKAT_2025_005.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_006','2025-10-04','FIDESZ-TÁBOR','STATE','Állami hirdetés (Családi adócsökkentés)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„A családi adócsökkentés az Ön családjának is jár!”','Mosolygó, világos ruhás magyar család közös étkezés közben, meleg, napfényes megvilágítású életkép kormányzati arculati sávval.','Óriásplakát / Eurobillboard (504 x 238 cm, 12 m²)','POSITIVE','Pozitív jóléti / Gondoskodó állam','Gyermekes családok, középosztály','Meleg színhőmérséklet, harmonikus családi asztal: a biztonságot nyújtó kormányzat vizuális ellenpontja a hideg kék „bábozós” plakátoknak.','A bábozós negatív konzultációs plakátokkal egy időben futó pozitív állami imázskampány (jó zsaru / rossz zsaru kommunikációs kettős).','HVG','Túry Gergely / HVG','Budapest','https://hvg.hu/itthon/20251004_Ursula-Von-der-Leyen-babozas-nemzeti-konzultacio-plakat-ebx','vagott_kepek/HUN_PLAKAT_2025_006.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2025_007','2025-12-04','FIDESZ-TÁBOR','PARTY','Helyi egyéni választókerületi teaser plakát','Hegyvidéki Fidesz-kampány (Budapest XII. kerület)','„Ki az a Steiner Attila?”','Fekete-fehér stílusú, férfi sziluettet és kérdőjelet használó figyelemfelkeltő (teaser) plakát a budapesti XII. kerületben, pártlogó nélküli rejtélyes arculattal.','Oszlopplakát / Citylight (B1: 70 x 100 cm)','MOBILIZING','Figyelemfelkeltő (Teaser) / Névismertség-építő','Budapest XII. kerületi választók','Kereskedelmi reklámokból átvett „teaser” (kíváncsiságkeltő) technika: a pártlogó elhagyása csökkenti a billegő választók kezdeti kognitív ellenállását.','Magyar Péter hegyvidéki választókerületében kihelyezett bevezető kampányplakát a fideszes jelölt, Steiner Attila névismertségének felépítésére.','444.hu','Kovács Gergely / Facebook (444.hu)','Budapest, XII. kerület','https://444.hu/2025/12/04/ki-az-a-steiner-attila-feliratu-plakatok-jelentek-meg-magyar-peter-valasztokeruleteben','vagott_kepek/HUN_PLAKAT_2025_007.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_008','2026-02-04','FIDESZ-TÁBOR','STATE','Állami hirdetés (Nemzeti Petíció 2026)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„Üzenjük Brüsszelnek: NEM FIZETÜNK! – Nemzeti Petíció”','Hosszú utcai plakátsoron (pocsolyában tükröződve) váltakozó állami és NEM-plakátok: bal oldalon Volodimir Zelenszkij nyújtott, pénzt kérő tenyérrel, mellette rámutató Ursula von der Leyen és Manfred Weber; jobb oldalon piros stoptábla-nyolcszögben NEM FIZETÜNK! felirat.','Óriásplakát / Eurobillboard (504 x 238 cm, 12 m²)','NEGATIVE','Pénzügyi elrettentő / Szuverenitásvédelmi','Volodimir Zelenszkij, Ursula von der Leyen, Manfred Weber','A néző felé kinyújtott üres tenyér (követelőzés) és a KRESZ stoptáblát idéző vörös nyolcszög („NEM FIZETÜNK!”) azonnali zsigeri elutasítást vált ki.','A hivatalos kampányidőszak indulása előtt kihelyezett állami plakátkampány, amely az EU Ukrajna-támogatását közvetlen magyar adófizetői veszteségként mutatta be.','Telex','Huszti István / Telex','Budapest / Pécs / Országos','https://telex.hu/belfold/2026/02/21/kampanyidoszak-ajanlasok-gyujtese-jeloles-legfontosabb-tudnivalok','vagott_kepek/HUN_PLAKAT_2026_008.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_009','2026-02-04','FIDESZ-TÁBOR','PROXY','Harmadik feles negatív kampány (NEM sorozat)','Nemzeti Ellenállás Mozgalom (Ellenállás Mozgalom Non-Profit Kft. – Apáti Bence)','„ADÓEMELÉST! / GÁZÁREMELÉST! – IGENIS! – NEM TUD NEKIK NEMET MONDANI” + „ÉN, A KÉTARCÚ”','Az óbudai Szentendrei úti 8-as plakátfal előtte-utána fotón: balra a „Nem fizetünk!”, a „Nem tud nekik nemet mondani” (parancsoló Von der Leyen, meghajló Magyar Péter) és az „Én, a kétarcú” (kék-sárga brüsszeli maszkos Magyar Péter) óriásplakátok; jobbra a választás után világoskék papírral teljesen leragasztott üres táblák.','Óriásplakát-fal / Eurobillboard mátrix (8 x 12 m²)','NEGATIVE','Totális vizuális bekerítés / Karaktergyilkosság','Magyar Péter, Ursula von der Leyen','Színházi maszk-metafora („Én, a kétarcú”) és parancs-engedelmesség dialógusbuborékok („Adóemelést! – Igenis!”); a jobb oldali fotón a választás utáni azonnali vizuális tabula rasa.','A 2026-os kampány legnagyobb példányszámú negatív plakátsorozata, amely a Szentendrei úti plakátfalon a hivatalos Fidesz-jelölti (Kepes Ádám) és kormányzati plakátokkal szimbiózisban jelent meg.','24.hu','Kőrös Gábor / 24.hu','Budapest, III. kerület Kaszásdűlő (Szentendrei út)','https://24.hu/belfold/2026/04/17/obudai-plakatokkal-boritott-haz-vereseg-utan/','vagott_kepek/HUN_PLAKAT_2026_009.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_010','2026-02-24','FIDESZ-TÁBOR','PARTY','Hivatalos párt- és egyéni jelölti választási plakát','Fidesz – Magyar Polgári Szövetség – KDNP','„Berkó Attila – A BIZTOS VÁLASZTÁS (Fidesz–KDNP)”','Kétoszlopos sajtófotó: bal oldalon Berkó Attila (Fidesz–KDNP) fehér hátterű, narancssárga sávos „A BIZTOS VÁLASZTÁS” kandeláberplakátja nemzeti színű sarokívvel; jobb oldalon összehasonlításképp Mészáros Dávid (DK) „Szavazz a baloldal jelöltjére!” választási plakátja.','Oszlop-/kandeláberplakát (B1: 70 x 100 cm) és Óriásplakát','POSITIVE','Pozitív / Stabilitásközpontú jelölti imázs','Jász-Nagykun-Szolnok megye 1. OEVK választói / Országos','Letisztult fehér háttér, nyugodt portré, nemzeti trikolór és narancssárga sáv: a hivatalos pártplakát teljesen mentes a negatív elemektől, kiszervezve a konfliktust a proxyknak.','A Fidesz–KDNP hivatalos 2026-os pártkampányának központi arculata a kiszámíthatóságot („A biztos választás”) hangsúlyozta, éles munkamegosztásban az állami és NEM-plakátokkal.','Szolnok TV / Hírös.hu','Szolnok TV','Szolnok / Országos','https://www.szolnoktv.hu/hirek/egyre-tobb-a-valasztasi-plakat','vagott_kepek/HUN_PLAKAT_2026_010.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_011','2026-04-08','FIDESZ-TÁBOR','STATE','Állami hirdetés (Kampányhajrá gazdasági kampány)','Magyarország Kormánya (Miniszterelnöki Kabinetiroda)','„95: 595 Ft/liter | D: 615 Ft/liter – VÉDETT ÁR – A benzin és a gázolaj hazánkban a legolcsóbb Európában”','Duna-parti útszakasz mellett álló kék kormányzati óriásplakát: bal oldalon benzinkút-árkijelző grafika (95: 595 Ft, D: 615 Ft), piros „VÉDETT ÁR” címke és tankoló pisztoly; jobb oldalon nemzeti pajzs és fehér-arany tipográfia.','Óriásplakát / Eurobillboard (504 x 238 cm, 12 m²)','POSITIVE','Jóléti védőpajzs / Kampányhajrá ígéret','Autósok, ingázók, árérzékeny választók','Konkrét numerikus horgonyzás (595 Ft / 615 Ft Totem-számjegyek) és a „Védett ár” katonai-gondoskodó kifejezés: az állam mint a mindennapi megélhetés garantálója.','A választás előtti utolsó héten indított állami plakátkampány, amely az inflációs és megélhetési aggodalmakat közvetlen hatósági árkommunikációval igyekezett semlegesíteni.','Telex','Zách Dániel / Telex','Budapest (rakpart) / Országos','https://telex.hu/gazdasag/2026/04/08/benzin-gazolaj-uzemanyag-tankolas-kampany-propaganda','vagott_kepek/HUN_PLAKAT_2026_011.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_012','2026-02-25','TISZA PÁRT','PARTY','Hivatalos egyéni képviselőjelölti választási plakát','TISZA – Tisztelet és Szabadság Párt','„TISZA – VÁLASZTÁS 2026 (106 egyéni jelölti portré és név)”','Kandeláberekre és villanyoszlopokra rögzített B1/A1-es jelölti hullámpolitén táblák kék-fehér-piros TISZA arculattal és az egyéni jelöltek portréjával.','Kandeláber- és villanyoszlop-plakát (B1: 70 x 100 cm)','MOBILIZING','Helyi jelöltépítő / Intézményesülő','106 egyéni választókerület választói','Egységes országos vizuális sablon helyi arcokkal: a mozgalomból kormányzóképes párttá válás demonstrálása az utcai oszlopokon.','Az óriásplakát-cégek bojkottja miatt a TISZA Párt hivatalos közterületi jelölti kampánya kizárólag kandeláberekre rögzített táblákon zajlott.','Kanizsa Médiaház / Szolnok TV','Kanizsa Médiaház','Nagykanizsa / Szolnok / Országos','https://kanizsamediahaz.hu/hir/202603/plakaterdo-mar-kanizsat-is-elleptek-a-valasztasi-plakatok','vagott_kepek/HUN_PLAKAT_2026_012.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
INSERT INTO "posters" VALUES('HUN_PLAKAT_2026_013','2026-03-01','TISZA PÁRT','GRASSROOTS','Lakossági erkély-, ablak- és kerítéskampány','TISZA – Tisztelet és Szabadság Párt (Szimpatizánsok otthonai)','„TISZA – MOST VAGY SOHA!”','Kertvárosi családi ház fakerítésére kihelyezett három TISZA-hirdetés egymás mellett: bal oldalon Magyar Péter és a helyi jelölt (Bujdosó Andrea Anna) közös plakátja, középen kisebb tábla, jobb oldalon nagy sötétkék molinó „MOST VAGY SOHA!” felirattal (a „vagy soha!” piros vonallal áthúzva).','Lakossági kerítésmolinó (200 x 100 cm) és kertplakát (A2/B2)','MOBILIZING','Grassroots mobilizáló / Történelmi sorsfordító','Szomszédsági közösségek, helyi választók','1848-as történelmi intertextualitás („Most vagy soha!”), ahol a „vagy soha” piros áthúzása a vereség lehetőségét is kizáró elszántságot kódolja; a magánkerítés személyes garanciavállalást jelent.','Az óriásplakát-piac állami és kormánypárti dominanciáját a TISZA Párt a szimpatizánsok saját ingatlanjainak (kerítések, erkélyek, ablakok) hirdetőfelületté alakításával kerülte meg.','444.hu / HVG','Bábel Vilmos / 444.hu','Országos (lakossági kerítések és erkélyek)','https://444.hu/2026/03/01/a-tiszasok-az-otthonaikra-erositett-plakatokkal-szallnak-be-a-kampanyba','vagott_kepek/HUN_PLAKAT_2026_013.jpg','LETÖLTVE ÉS VÁGVA (100% Ellenőrzött sajtófotó)');
COMMIT;
